/**
* 密钥设置界面 —— 网页版新增。
*
* 原插件的密钥由 DSH 凭据 / 环境变量提供，界面上只有一句「去 platform.agnes-ai.cn
* 创建密钥」的引导，**没有输入框**。网页版反过来：密钥归使用者自己，
* 所以必须给一个填写入口。
*
* 填好的密钥写进 localStorage（见 studio.ts 的 setLocalKeys），
* 之后每个请求都会随 `x-vendor-keys` 请求头发给服务端转发，服务端不保存。
*/
/** 支持的厂商（与原插件 vendors.ts 的六家一致）。 */
const VENDORS = [
	{
		id: "agnes",
		label: "Agnes"
	},
	{
		id: "deepseek",
		label: "DeepSeek"
	},
	{
		id: "qwen",
		label: "通义千问 Qwen"
	},
	{
		id: "doubao",
		label: "豆包 / 火山方舟"
	},
	{
		id: "minimax",
		label: "MiniMax"
	},
	{
		id: "ollama",
		label: "Ollama（本地服务）",
		keyless: true
	}
];
const CSS = `
.swk-fab {
  position: fixed; right: 18px; bottom: 18px; z-index: 99990;
  display: flex; align-items: center; gap: 7px;
  padding: 10px 15px; border-radius: 999px; border: 1px solid rgba(160,190,215,.5);
  background: rgba(255,255,255,.94); color: #2a4a6a;
  font: 600 13px/1 'Inter', system-ui, -apple-system, 'PingFang SC', 'Microsoft YaHei', sans-serif;
  cursor: pointer; box-shadow: 0 8px 24px rgba(60,90,130,.16);
  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
  transition: transform .18s, box-shadow .18s, border-color .18s;
}
.swk-fab:hover { transform: translateY(-2px); box-shadow: 0 12px 28px rgba(60,90,130,.22); border-color: rgba(74,144,217,.6); }
.swk-fab:focus-visible { outline: 2px solid #4a90d9; outline-offset: 2px; }
.swk-fab .dot { width: 7px; height: 7px; border-radius: 999px; background: #8fa3b8; }
.swk-fab[data-ok="true"] .dot { background: #4caf8f; box-shadow: 0 0 7px rgba(76,175,143,.7); }

.swk-mask {
  position: fixed; inset: 0; z-index: 99991;
  display: flex; align-items: center; justify-content: center; padding: 18px;
  background: rgba(10,20,36,.5);
  backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
}
.swk-mask[hidden] { display: none; }
.swk-card {
  width: min(480px, 100%); max-height: 86vh; overflow-y: auto;
  padding: 20px; border-radius: 22px;
  background: #fff; border: 1px solid rgba(180,200,225,.5);
  box-shadow: 0 20px 50px rgba(40,60,90,.28);
  font: 14px/1.7 'Inter', system-ui, -apple-system, 'PingFang SC', 'Microsoft YaHei', sans-serif;
  color: #1a2a3a;
}
.swk-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.swk-head h2 { margin: 0; font-size: 16px; font-weight: 700; color: #2a4a6a; }
.swk-x {
  width: 30px; height: 30px; border-radius: 999px; border: 1px solid rgba(160,190,215,.4);
  background: rgba(230,240,250,.6); color: #3d5f7f; cursor: pointer; font-size: 14px;
}
.swk-x:hover { background: rgba(180,205,230,.55); }

.swk-tip {
  padding: 11px 13px; margin-bottom: 16px; border-radius: 12px;
  border: 1px solid rgba(60,150,120,.35); background: rgba(76,175,143,.09);
  font-size: 12.5px; line-height: 1.65; color: #28594a;
}
.swk-tip strong { display: block; margin-bottom: 3px; color: #1c4b3c; }
.swk-tip code { background: rgba(74,144,217,.13); padding: 1px 5px; border-radius: 5px; color: #3a6aaa; }

.swk-row { margin-bottom: 12px; }
.swk-row label {
  display: block; margin-bottom: 5px; font-size: 11.5px; font-weight: 600;
  letter-spacing: .4px; color: #4d5f72;
}
.swk-row label .lk { margin-left: 6px; font-weight: 500; color: #3a6aaa; letter-spacing: 0; }
.swk-row input {
  width: 100%; box-sizing: border-box; padding: 10px 12px;
  border: 1px solid rgba(160,190,215,.4); border-radius: 11px;
  background: #f0f4fc; color: #1a2a3a; font: inherit; font-size: 13.5px; outline: none;
  transition: border-color .18s, box-shadow .18s, background .18s;
}
.swk-row input:focus { border-color: #7db9f2; background: #fff; box-shadow: 0 0 0 3px rgba(125,185,242,.28); }
.swk-row input:disabled { opacity: .55; cursor: not-allowed; }

.swk-foot { display: flex; justify-content: space-between; gap: 10px; margin-top: 18px; }
.swk-btn {
  padding: 10px 18px; border-radius: 999px; border: 1px solid rgba(160,190,215,.4);
  background: #fff; color: #3a4a5a; font: 600 13.5px/1 inherit; cursor: pointer;
  transition: background .18s, border-color .18s, transform .14s;
}
.swk-btn:hover { background: #f0f4fc; border-color: rgba(74,144,217,.5); }
.swk-btn:focus-visible { outline: 2px solid #4a90d9; outline-offset: 2px; }
.swk-btn:active { transform: translateY(1px); }
.swk-btn.primary {
  background: linear-gradient(135deg, #4a90d9, #3a6aaa);
  border-color: transparent; color: #fff;
  box-shadow: 0 4px 14px rgba(74,144,217,.32);
}
.swk-btn.primary:hover { background: linear-gradient(135deg, #5c9ee0, #4a90d9); }
.swk-ok { margin-top: 12px; font-size: 12.5px; color: #2f6b58; min-height: 18px; }
`;
/**
* 挂载密钥设置入口（右下角浮动按钮 + 弹窗）。
* @returns 卸载函数。
*/
function mountKeyUI() {
	const styleEl = document.createElement("style");
	styleEl.id = "studio-web-keyui";
	styleEl.textContent = CSS;
	document.head.appendChild(styleEl);
	const fab = document.createElement("button");
	fab.type = "button";
	fab.className = "swk-fab";
	fab.title = "设置 API 密钥（只存在你自己的浏览器里）";
	fab.innerHTML = "<span class=\"dot\"></span><span>密钥</span>";
	const syncFab = () => {
		fab.dataset.ok = Object.keys(getLocalKeys()).length > 0 ? "true" : "false";
	};
	syncFab();
	document.body.appendChild(fab);
	const mask = document.createElement("div");
	mask.className = "swk-mask";
	mask.hidden = true;
	const card = document.createElement("div");
	card.className = "swk-card";
	card.setAttribute("role", "dialog");
	card.setAttribute("aria-modal", "true");
	card.setAttribute("aria-label", "API 密钥设置");
	const head = document.createElement("div");
	head.className = "swk-head";
	const h2 = document.createElement("h2");
	h2.textContent = "⚙ API 密钥";
	const closeBtn = document.createElement("button");
	closeBtn.type = "button";
	closeBtn.className = "swk-x";
	closeBtn.setAttribute("aria-label", "关闭");
	closeBtn.textContent = "✕";
	head.append(h2, closeBtn);
	const tip = document.createElement("div");
	tip.className = "swk-tip";
	tip.innerHTML = "<strong>🔐 密钥只存在这台设备的浏览器里</strong>填入后保存在 <code>localStorage</code>，随每次请求发给你自己部署的这一个服务、再转发给厂商。<u>服务端不保存、不写日志、不落盘</u>——容器被人拖走也拿不到能花钱的凭据。共用电脑请用完清空。";
	card.append(head, tip);
	const inputs = [];
	const saved = getLocalKeys();
	for (const v of VENDORS) {
		const row = document.createElement("div");
		row.className = "swk-row";
		const label = document.createElement("label");
		label.textContent = v.label;
		if (v.keyless) {
			const lk = document.createElement("span");
			lk.className = "lk";
			lk.textContent = "（本地服务，无需密钥）";
			label.appendChild(lk);
		}
		const input = document.createElement("input");
		input.type = "password";
		input.autocomplete = "off";
		input.spellcheck = false;
		input.placeholder = v.keyless ? "无需填写" : `粘贴你的 ${v.label} API Key`;
		input.value = saved[v.id] ?? "";
		input.disabled = v.keyless === true;
		row.append(label, input);
		card.appendChild(row);
		inputs.push({
			id: v.id,
			el: input
		});
	}
	const foot = document.createElement("div");
	foot.className = "swk-foot";
	const clearBtn = document.createElement("button");
	clearBtn.type = "button";
	clearBtn.className = "swk-btn";
	clearBtn.textContent = "清空全部";
	const saveBtn = document.createElement("button");
	saveBtn.type = "button";
	saveBtn.className = "swk-btn primary";
	saveBtn.textContent = "保存";
	foot.append(clearBtn, saveBtn);
	const ok = document.createElement("div");
	ok.className = "swk-ok";
	card.append(foot, ok);
	mask.appendChild(card);
	document.body.appendChild(mask);
	const open = () => {
		mask.hidden = false;
		inputs[0]?.el.focus();
	};
	const close = () => {
		mask.hidden = true;
		ok.textContent = "";
	};
	const collect = () => {
		const out = {};
		for (const { id, el } of inputs) {
			const val = el.value.trim();
			if (val) out[id] = val;
		}
		return out;
	};
	fab.addEventListener("click", open);
	closeBtn.addEventListener("click", close);
	mask.addEventListener("click", (e) => {
		if (e.target === mask) close();
	});
	saveBtn.addEventListener("click", () => {
		setLocalKeys(collect());
		syncFab();
		ok.textContent = "✓ 已保存到本机浏览器";
	});
	clearBtn.addEventListener("click", () => {
		for (const { el } of inputs) el.value = "";
		setLocalKeys({});
		syncFab();
		ok.textContent = "已清空";
	});
	document.addEventListener("keydown", (e) => {
		if (e.key === "Escape" && !mask.hidden) close();
	});
	if (Object.keys(saved).length === 0) setTimeout(open, 600);
	return () => {
		fab.remove();
		mask.remove();
		styleEl.remove();
	};
}
